-- Formulas
INSERT OR IGNORE INTO formulas (id, subject_id, slug, name, latex, description, variables, status) VALUES ('frm_3a7d5741cdadfe', 'subj_phys', 'kinematic-equations', 'Constant-acceleration equations', 'v = v_0 + at, \quad \Delta x = v_0t + \tfrac{1}{2}at^2, \quad v^2 = v_0^2 + 2a\Delta x, \quad \Delta x = \tfrac{v_0 + v}{2}t', 'The four equations of motion for constant acceleration along a line. Pick the one that leaves out the quantity you don''t know.', '[{"symbol":"v_0, v","meaning":"initial and final velocity","unit":"m/s"},{"symbol":"a","meaning":"acceleration","unit":"m/s²"},{"symbol":"\\Delta x","meaning":"displacement","unit":"m"},{"symbol":"t","meaning":"time","unit":"s"}]', 'published');
INSERT OR IGNORE INTO formulas (id, subject_id, slug, name, latex, description, variables, status) VALUES ('frm_a4fbeeb1eea975', 'subj_phys', 'centripetal-acceleration', 'Centripetal acceleration and force', 'a_c = \frac{v^2}{r} = \omega^2 r, \qquad F_c = \frac{mv^2}{r}, \qquad v = \frac{2\pi r}{T}', 'Acceleration toward the center for motion in a circle at constant speed, and the net inward force that causes it.', '[{"symbol":"v","meaning":"speed","unit":"m/s"},{"symbol":"r","meaning":"radius","unit":"m"},{"symbol":"T","meaning":"period","unit":"s"}]', 'published');
INSERT OR IGNORE INTO formulas (id, subject_id, slug, name, latex, description, variables, status) VALUES ('frm_e5f9c7e0f294e6', 'subj_phys', 'universal-gravitation', 'Universal gravitation', 'F_g = \frac{Gm_1m_2}{r^2}, \qquad G = 6.67 \times 10^{-11}\ \text{N·m}^2/\text{kg}^2', 'The attractive force between two masses whose centers are a distance r apart.', '[{"symbol":"m_1, m_2","meaning":"masses","unit":"kg"},{"symbol":"r","meaning":"center-to-center distance","unit":"m"}]', 'published');
INSERT OR IGNORE INTO formulas (id, subject_id, slug, name, latex, description, variables, status) VALUES ('frm_5cbfa1832f085e', 'subj_phys', 'work-energy', 'Work and the work–energy theorem', 'W = Fd\cos\theta, \qquad W_{\text{net}} = \Delta KE, \qquad PE_g = mgh, \qquad P = \frac{W}{t}', 'Work done by a constant force, the work–energy theorem, gravitational potential energy near Earth, and power.', '[{"symbol":"\\theta","meaning":"angle between force and displacement"},{"symbol":"h","meaning":"height above a reference level","unit":"m"},{"symbol":"P","meaning":"power","unit":"W"}]', 'published');
INSERT OR IGNORE INTO formulas (id, subject_id, slug, name, latex, description, variables, status) VALUES ('frm_b0592d6f1798da', 'subj_phys', 'momentum-impulse', 'Momentum and impulse', '\vec{p} = m\vec{v}, \qquad \vec{J} = \vec{F}\Delta t = \Delta\vec{p}', 'Momentum is mass times velocity; the impulse of a force equals the change in momentum it causes.', '[{"symbol":"p","meaning":"momentum","unit":"kg·m/s"},{"symbol":"J","meaning":"impulse","unit":"N·s"}]', 'published');

-- Lesson: acceleration-motion-graphs
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_86eba9e5151376', 'acceleration-motion-graphs', 'Acceleration and motion graphs', 'Define acceleration as the rate of change of velocity, and move between position-time, velocity-time and acceleration-time graphs using slopes and areas.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_25cd79f6bfef54', 'les_86eba9e5151376', 1, 'Compute average acceleration Δv/Δt.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_b9782020e2daf0', 'les_86eba9e5151376', 2, 'Read acceleration as the slope of a velocity-time graph.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_067563d236d637', 'les_86eba9e5151376', 3, 'Read displacement as the area under a velocity-time graph.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_25cd79f6bfef54', 'les_86eba9e5151376', 'learn', 1, 'definition', '{"term":"Acceleration","body":"$a = \\frac{\\Delta v}{\\Delta t}$, in m/s². An object speeds up when velocity and acceleration point the same way, and slows down when they point opposite ways."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b9782020e2daf0', 'les_86eba9e5151376', 'learn', 2, 'worked_example', '{"title":"A car goes from 0 to 27 m/s in 9 s","steps":[{"latex":"a = \\tfrac{27 - 0}{9} = 3\\ \\text{m/s}^2","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_067563d236d637', 'les_86eba9e5151376', 'learn', 3, 'definition', '{"term":"Reading graphs","body":"On a velocity-time graph, slope = acceleration and area between the graph and the time axis = displacement (area below the axis counts as negative)."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f195b5dcc2c7b4', 'les_86eba9e5151376', 'learn', 4, 'worked_example', '{"title":"Velocity rises steadily from 0 to 10 m/s in 4 s","steps":[{"latex":"\\text{slope} = 2.5\\ \\text{m/s}^2","explanation":""},{"latex":"\\text{area} = \\tfrac{1}{2}(4)(10) = 20\\ \\text{m}","explanation":"Displacement."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_bf704fce76908b', 'les_86eba9e5151376', 'experiment', 5, 'activity', '{"activity":"motion-graphs","title":"Throw the cart forward against a backward push","params":{"v0":8,"a":-2,"x0":0,"t":4}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_cde495d391b038', 'les_86eba9e5151376', 'experiment', 6, 'callout', '{"tone":"tip","title":"Try this","body":"At $t = 4$ s the velocity graph crosses zero: the cart stops and turns around, and the position graph peaks."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_88b986daa6212a', 'les_86eba9e5151376', 'learn', 7, 'callout', '{"tone":"application","title":"Where this shows up","body":"Car reviews quote 0–100 km/h times, which are average accelerations; crash investigators read skid marks to work backward to initial speeds."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_25cd79f6bfef54', 'les_86eba9e5151376', 1, 'practice', 'numeric', 1, 'A bike slows from 12 m/s to 4 m/s in 2 s. Find its acceleration.', '{"answer":-4,"unit":"m/s²"}', '[]', '$\frac{4 - 12}{2}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_b9782020e2daf0', 'les_86eba9e5151376', 2, 'practice', 'multiple_choice', 2, 'Velocity is −5 m/s and acceleration is −2 m/s². The object is…', '{"choices":["speeding up","slowing down","at rest","moving at constant speed"],"answer":0}', '[]', 'Same signs: speeding up (in the negative direction).');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_067563d236d637', 'les_86eba9e5151376', 3, 'practice', 'numeric', 2, 'A velocity-time graph is constant at 6 m/s from $t = 0$ to $t = 5$ s. Find the displacement.', '{"answer":30,"unit":"m"}', '[]', 'Rectangle area $6 \times 5$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_f195b5dcc2c7b4', 'les_86eba9e5151376', 4, 'review', 'multiple_choice', 3, 'A position-time graph is a parabola opening upward. The acceleration is…', '{"choices":["zero","positive and constant","negative and constant","increasing"],"answer":1}', '[]', '$x = x_0 + v_0t + \frac{1}{2}at^2$ with $a > 0$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_95eabd63ac5b43', 'subj_phys', 'kinematics', 'Kinematics', 'Describing motion with position, velocity and acceleration.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_86eba9e5151376', (SELECT id FROM concepts WHERE slug = 'kinematics'));

-- Lesson: conservation-mechanical-energy
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_a41c1f40c76bac', 'conservation-mechanical-energy', 'Conservation of mechanical energy', 'Use KE + PE = constant (without friction) to find speeds and heights, and account for energy lost to friction as thermal energy.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_6f87047d3eb101', 'les_a41c1f40c76bac', 1, 'Apply KE₁ + PE₁ = KE₂ + PE₂ when only gravity and springs do work.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_c2a1b9a4cdfa90', 'les_a41c1f40c76bac', 2, 'Find speeds at different heights without knowing the path.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_3121f3728163d6', 'les_a41c1f40c76bac', 3, 'Include work done by friction: KE₁ + PE₁ = KE₂ + PE₂ + friction losses.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_6f87047d3eb101', 'les_a41c1f40c76bac', 'learn', 1, 'definition', '{"term":"Conservation","body":"If only conservative forces (gravity, springs) do work, total mechanical energy is constant: $\\frac{1}{2}mv_1^2 + mgh_1 = \\frac{1}{2}mv_2^2 + mgh_2$. Mass cancels when only gravity acts."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c2a1b9a4cdfa90', 'les_a41c1f40c76bac', 'learn', 2, 'worked_example', '{"title":"A roller coaster starts from rest 30 m up. How fast is it at a point 10 m up?","steps":[{"latex":"mg(30) = \\tfrac{1}{2}mv^2 + mg(10)","explanation":""},{"latex":"v = \\sqrt{2(9.8)(20)} \\approx 19.8\\ \\text{m/s}","explanation":"The shape of the track doesn''t matter."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3121f3728163d6', 'les_a41c1f40c76bac', 'learn', 3, 'worked_example', '{"title":"A 50 kg skier starts from rest 20 m up and reaches the bottom at 16 m/s. Energy lost to friction?","steps":[{"latex":"50(9.8)(20) = 9800\\ \\text{J}","explanation":"Initial PE."},{"latex":"\\tfrac{1}{2}(50)(16)^2 = 6400\\ \\text{J}","explanation":"Final KE."},{"latex":"9800 - 6400 = 3400\\ \\text{J}","explanation":"Became thermal energy."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e07ddfedf069ed', 'les_a41c1f40c76bac', 'experiment', 4, 'activity', '{"activity":"spring-oscillator","title":"Total energy stays constant"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_30fe187527ab28', 'les_a41c1f40c76bac', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Hydroelectric dams turn the potential energy of high water into kinetic energy and then electricity; pole vaulters convert running KE into elastic PE and then height."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_6f87047d3eb101', 'les_a41c1f40c76bac', 1, 'practice', 'numeric', 1, 'A ball is dropped from 20 m. Find its speed just before landing, to one decimal place.', '{"answer":19.8,"tolerance":0.05,"unit":"m/s"}', '[]', '$\sqrt{2(9.8)(20)}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_c2a1b9a4cdfa90', 'les_a41c1f40c76bac', 2, 'practice', 'numeric', 2, 'A pendulum bob passes the bottom at 3 m/s. How high above the bottom does it rise, to three decimal places?', '{"answer":0.459,"tolerance":0.002,"unit":"m"}', '[]', '$h = \frac{v^2}{2g} = \frac{9}{19.6}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_3121f3728163d6', 'les_a41c1f40c76bac', 3, 'practice', 'multiple_choice', 2, 'Two balls, 1 kg and 5 kg, roll from rest down the same frictionless ramp. At the bottom…', '{"choices":["the 5 kg ball is faster","the 1 kg ball is faster","they have equal speeds","they have equal kinetic energies"],"answer":2}', '[]', 'Mass cancels in $mgh = \frac{1}{2}mv^2$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_e07ddfedf069ed', 'les_a41c1f40c76bac', 4, 'review', 'numeric', 3, 'A 2 kg block leaves a spring ($k = 800$ N/m, compressed 0.2 m) on a frictionless floor. Find its speed.', '{"answer":4,"unit":"m/s"}', '[]', '$\frac{1}{2}(800)(0.04) = 16 = \frac{1}{2}(2)v^2$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_173d9168467e6c', 'subj_phys', 'energy', 'Work and energy', 'Work, kinetic and potential energy, conservation of energy and power.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_a41c1f40c76bac', (SELECT id FROM concepts WHERE slug = 'energy'));
