INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_a41c1f40c76bac', (SELECT id FROM formulas WHERE slug = 'kinetic-energy'), 2);

-- Lesson: constant-acceleration-equations
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_034ca97daf59a2', 'constant-acceleration-equations', 'Equations for constant acceleration', 'Solve one-dimensional motion problems with the four constant-acceleration equations, choosing the equation that skips the unknown you don''t need.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_96f41da0737b5e', 'les_034ca97daf59a2', 1, 'List knowns and the unknown with signs.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_a5fe1060806e26', 'les_034ca97daf59a2', 2, 'Choose the kinematic equation that contains exactly the quantities involved.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_26e911dc8a8b05', 'les_034ca97daf59a2', 3, 'Solve stopping-distance and speed-up problems.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_96f41da0737b5e', 'les_034ca97daf59a2', 'learn', 1, 'definition', '{"term":"The four equations","body":"$v = v_0 + at$; $\\Delta x = v_0t + \\frac{1}{2}at^2$; $v^2 = v_0^2 + 2a\\Delta x$; $\\Delta x = \\frac{v_0 + v}{2}t$. Each leaves out one of $v$, $\\Delta x$, $t$, $v_0$ (or $a$)."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a5fe1060806e26', 'les_034ca97daf59a2', 'learn', 2, 'worked_example', '{"title":"A car at 20 m/s brakes at −5 m/s². How far does it go before stopping?","steps":[{"latex":"v_0 = 20,\\ v = 0,\\ a = -5,\\ \\Delta x = ?","explanation":"Time isn''t asked: use v² = v₀² + 2aΔx."},{"latex":"0 = 400 - 10\\Delta x \\Rightarrow \\Delta x = 40\\ \\text{m}","explanation":""},{"latex":"t = \\tfrac{0 - 20}{-5} = 4\\ \\text{s}","explanation":"If needed, v = v₀ + at."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_26e911dc8a8b05', 'les_034ca97daf59a2', 'experiment', 3, 'activity', '{"activity":"motion-graphs","title":"Braking to a stop","params":{"v0":10,"a":-2.5,"x0":0,"t":4}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a712aaaadceda9', 'les_034ca97daf59a2', 'learn', 4, 'callout', '{"tone":"warning","title":"Speed doubles, distance quadruples","body":"Stopping distance is $\\frac{v_0^2}{2|a|}$, so twice the speed needs four times the distance. This is why speed limits near schools are low."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_23f5282a9b21df', 'les_034ca97daf59a2', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Runway lengths, highway on-ramp lengths and the yellow-light timing at intersections are all designed with these equations."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_96f41da0737b5e', 'les_034ca97daf59a2', 1, 'practice', 'numeric', 1, 'From rest, a cart accelerates at 2 m/s² for 6 s. How far does it go?', '{"answer":36,"unit":"m"}', '[]', '$\frac{1}{2}(2)(36) = 36$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_a5fe1060806e26', 'les_034ca97daf59a2', 2, 'practice', 'numeric', 1, 'What is its speed at 6 s?', '{"answer":12,"unit":"m/s"}', '[]', '$0 + 2(6)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_26e911dc8a8b05', 'les_034ca97daf59a2', 3, 'practice', 'numeric', 2, 'A plane needs 70 m/s to take off and accelerates at 3.5 m/s² from rest. What runway length is needed?', '{"answer":700,"unit":"m"}', '[]', '$\Delta x = \frac{v^2}{2a} = \frac{4900}{7} = 700$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_a712aaaadceda9', 'les_034ca97daf59a2', 4, 'review', 'numeric', 3, 'A car at 30 m/s brakes at −6 m/s². What is its stopping distance?', '{"answer":75,"unit":"m"}', '[]', '$\frac{900}{12} = 75$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_95eabd63ac5b43', 'subj_phys', 'kinematics', 'Kinematics', 'Describing motion with position, velocity and acceleration.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_034ca97daf59a2', (SELECT id FROM concepts WHERE slug = 'kinematics'));
