-- Lesson: forces-on-inclines
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_15584befbac0e9', 'forces-on-inclines', 'Forces on inclines', 'Tilt the axes along a ramp, split gravity into mg sin θ and mg cos θ, and find accelerations and the angle at which objects start to slide.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_5bf309869015f5', 'les_15584befbac0e9', 1, 'Resolve weight into components parallel and perpendicular to an incline.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_6afaf1755dbbea', 'les_15584befbac0e9', 2, 'Find the normal force and acceleration on a ramp, with and without friction.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_d04b9e71e2b56c', 'les_15584befbac0e9', 3, 'Find the angle at which an object begins to slide (tan θ = μₛ).');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_5bf309869015f5', 'les_15584befbac0e9', 'learn', 1, 'definition', '{"term":"Tilted axes","body":"On a ramp at angle $\\theta$: gravity''s component along the slope is $mg\\sin\\theta$ and into the slope is $mg\\cos\\theta$. With no other perpendicular forces, $F_N = mg\\cos\\theta$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_6afaf1755dbbea', 'les_15584befbac0e9', 'learn', 2, 'worked_example', '{"title":"A 10 kg block on a frictionless 30° ramp","steps":[{"latex":"a = g\\sin 30° = 4.9\\ \\text{m/s}^2","explanation":"Independent of mass."},{"latex":"F_N = 10(9.8)\\cos 30° \\approx 84.9\\ \\text{N}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d04b9e71e2b56c', 'les_15584befbac0e9', 'learn', 3, 'worked_example', '{"title":"When does a block start to slide?","steps":[{"latex":"mg\\sin\\theta = \\mu_s mg\\cos\\theta","explanation":"At the tipping point."},{"latex":"\\tan\\theta = \\mu_s","explanation":"With μₛ = 0.5, θ ≈ 26.6°."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e7fc28d1981442', 'les_15584befbac0e9', 'experiment', 4, 'activity', '{"activity":"forces-incline","title":"Tilt until it slides"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_03c0883ffeed01', 'les_15584befbac0e9', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Wheelchair ramp codes, road grades and the angle at which snow avalanches all come down to $\\tan\\theta$ compared with a friction coefficient."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_5bf309869015f5', 'les_15584befbac0e9', 1, 'practice', 'numeric', 1, 'Find the acceleration of a block sliding down a frictionless 45° ramp, to two decimal places.', '{"answer":6.93,"tolerance":0.01,"unit":"m/s²"}', '[]', '$9.8\sin 45° \approx 6.93$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_6afaf1755dbbea', 'les_15584befbac0e9', 2, 'practice', 'numeric', 2, 'A 4 kg block rests on a 20° ramp. Find the normal force, to one decimal place.', '{"answer":36.8,"tolerance":0.1,"unit":"N"}', '[]', '$4(9.8)\cos 20° \approx 36.8$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_d04b9e71e2b56c', 'les_15584befbac0e9', 3, 'practice', 'numeric', 2, 'A box slides down a 30° ramp with $\mu_k = 0.2$. Find its acceleration, to two decimal places.', '{"answer":3.2,"tolerance":0.01,"unit":"m/s²"}', '[]', '$g(\sin 30° - 0.2\cos 30°) = 9.8(0.5 - 0.1732) \approx 3.20$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_e7fc28d1981442', 'les_15584befbac0e9', 4, 'review', 'numeric', 3, 'At what angle, in degrees, does a block with $\mu_s = 0.7$ begin to slide? One decimal place.', '{"answer":35,"tolerance":0.1,"unit":"°"}', '[]', '$\tan^{-1} 0.7 \approx 35.0°$.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_15584befbac0e9', (SELECT id FROM concepts WHERE slug = 'newtons-laws'));
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_ded4ddbc4c2866', 'subj_phys', 'friction', 'Friction', 'Forces that oppose sliding between surfaces in contact.');
