-- Lesson: free-body-diagrams
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_cfa7bd3f4446d1', 'free-body-diagrams', 'Free-body diagrams', 'Draw free-body diagrams with every force on one object, write Newton''s second law along each axis, and solve for unknown forces and accelerations, including in elevators.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_0648d07b6b7d01', 'les_cfa7bd3f4446d1', 1, 'Identify weight, normal force, tension, friction and applied forces.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_6a1b4e27c5bd1b', 'les_cfa7bd3f4446d1', 2, 'Draw one arrow per force acting on the chosen object.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_f950c7802410dc', 'les_cfa7bd3f4446d1', 3, 'Apply ΣF = ma along chosen axes.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0648d07b6b7d01', 'les_cfa7bd3f4446d1', 'learn', 1, 'definition', '{"term":"Common forces","body":"Weight $mg$ (down); normal force $F_N$ (perpendicular to a surface, pushing); tension $T$ (along a rope, pulling); friction (along a surface, opposing sliding); applied forces."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_6a1b4e27c5bd1b', 'les_cfa7bd3f4446d1', 'learn', 2, 'worked_example', '{"title":"A 5 kg mass hangs from a cable in an elevator accelerating upward at 2 m/s²","steps":[{"latex":"T - mg = ma","explanation":"Up is positive."},{"latex":"T = 5(9.8 + 2) = 59\\ \\text{N}","explanation":"More than the weight, 49 N."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f950c7802410dc', 'les_cfa7bd3f4446d1', 'learn', 3, 'worked_example', '{"title":"A 60 kg person stands on a scale in an elevator accelerating downward at 1.5 m/s²","steps":[{"latex":"mg - F_N = ma","explanation":"Down is positive."},{"latex":"F_N = 60(9.8 - 1.5) = 498\\ \\text{N}","explanation":"The scale reads less than the weight (588 N)."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_5d16bad34d7138', 'les_cfa7bd3f4446d1', 'experiment', 4, 'activity', '{"activity":"forces-incline","title":"A free-body diagram on a ramp"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_6deda9c57e0df0', 'les_cfa7bd3f4446d1', 'learn', 5, 'callout', '{"tone":"warning","title":"Only forces ON the object","body":"Don''t include forces the object exerts on others, and don''t add \"ma\" as a force. Velocity isn''t a force either."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d4c70f84b469ca', 'les_cfa7bd3f4446d1', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"Structural engineers draw free-body diagrams of every joint in a bridge; elevator designers use them to size cables for the largest acceleration."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_0648d07b6b7d01', 'les_cfa7bd3f4446d1', 1, 'practice', 'numeric', 1, 'A 2 kg book rests on a table. What normal force acts on it, in newtons?', '{"answer":19.6,"tolerance":0.01,"unit":"N"}', '[]', '$F_N = mg$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_6a1b4e27c5bd1b', 'les_cfa7bd3f4446d1', 2, 'practice', 'numeric', 2, 'A 10 kg box is pulled across a frictionless floor by a 30 N horizontal rope. Find its acceleration.', '{"answer":3,"unit":"m/s²"}', '[]', '$\frac{30}{10}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_f950c7802410dc', 'les_cfa7bd3f4446d1', 3, 'practice', 'numeric', 2, 'A 70 kg person in an elevator accelerating upward at 1 m/s² stands on a scale. What does the scale read, in newtons?', '{"answer":756,"unit":"N"}', '[]', '$70(9.8 + 1) = 756$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_5d16bad34d7138', 'les_cfa7bd3f4446d1', 4, 'review', 'multiple_choice', 3, 'Which force does NOT belong on a free-body diagram of a block sliding down a ramp?', '{"choices":["Weight","Normal force","Friction","The force the block exerts on the ramp"],"answer":3}', '[]', 'That force acts on the ramp.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_cfa7bd3f4446d1', (SELECT id FROM concepts WHERE slug = 'free-body-diagrams'));
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_cfa7bd3f4446d1', (SELECT id FROM concepts WHERE slug = 'newtons-laws'));

-- Lesson: free-fall
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_535529376717dc', 'free-fall', 'Free fall', 'Model objects moving only under gravity with constant acceleration g = 9.8 m/s² downward, for drops and upward throws.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_779c3c9d8d69ed', 'les_535529376717dc', 1, 'Use a = −9.8 m/s² (taking up as positive) for free fall.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_715c5b5676390a', 'les_535529376717dc', 2, 'Find fall times and impact speeds.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_94145c699e094b', 'les_535529376717dc', 3, 'Analyze an upward throw: time to the top, maximum height and symmetry.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_779c3c9d8d69ed', 'les_535529376717dc', 'learn', 1, 'definition', '{"term":"Free fall","body":"Ignoring air resistance, every object near Earth''s surface accelerates downward at $g = 9.8$ m/s², whatever its mass. At the top of a throw the velocity is 0, but the acceleration is still $-9.8$ m/s²."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_715c5b5676390a', 'les_535529376717dc', 'learn', 2, 'worked_example', '{"title":"A stone is dropped from 45 m. How long does it fall, and how fast is it going?","steps":[{"latex":"45 = \\tfrac{1}{2}(9.8)t^2 \\Rightarrow t \\approx 3.03\\ \\text{s}","explanation":"Taking down as positive here."},{"latex":"v = \\sqrt{2(9.8)(45)} \\approx 29.7\\ \\text{m/s}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_94145c699e094b', 'les_535529376717dc', 'learn', 3, 'worked_example', '{"title":"A ball is thrown up at 19.6 m/s","steps":[{"latex":"t_{\\text{top}} = \\tfrac{19.6}{9.8} = 2\\ \\text{s}","explanation":"v = 0 at the top."},{"latex":"h_{\\max} = \\tfrac{19.6^2}{2(9.8)} = 19.6\\ \\text{m}","explanation":""},{"latex":"\\text{back to the hand at } t = 4\\ \\text{s, at 19.6 m/s downward}","explanation":"Symmetry."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ae4e0be700752d', 'les_535529376717dc', 'experiment', 4, 'activity', '{"activity":"motion-graphs","title":"A vertical throw (up is positive)","params":{"v0":10,"a":-5,"x0":0,"t":2}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_5ad3eefcf6ef76', 'les_535529376717dc', 'experiment', 5, 'callout', '{"tone":"note","title":"About the sim","body":"The sim''s acceleration slider stops at ±5 m/s², so it shows a gentler \"gravity\"; the shapes of the graphs are the same as for $g = 9.8$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_201d79615c3101', 'les_535529376717dc', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"Divers, basketball players and engineers designing drop tests all use free-fall equations; on the Moon, $g$ is about 1.6 m/s², so the same jump lasts six times longer."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_779c3c9d8d69ed', 'les_535529376717dc', 1, 'practice', 'numeric', 1, 'How fast is a dropped object moving after 2 s?', '{"answer":19.6,"tolerance":0.01,"unit":"m/s"}', '[]', '$9.8 \times 2$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_715c5b5676390a', 'les_535529376717dc', 2, 'practice', 'numeric', 2, 'How far does it fall in those 2 s?', '{"answer":19.6,"tolerance":0.01,"unit":"m"}', '[]', '$\frac{1}{2}(9.8)(4)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_94145c699e094b', 'les_535529376717dc', 3, 'practice', 'numeric', 2, 'A ball is thrown up at 14.7 m/s. How long until it reaches the top?', '{"answer":1.5,"tolerance":0.001,"unit":"s"}', '[]', '$\frac{14.7}{9.8}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_ae4e0be700752d', 'les_535529376717dc', 4, 'review', 'multiple_choice', 3, 'At the very top of its flight, a ball thrown straight up has…', '{"choices":["zero velocity and zero acceleration","zero velocity and acceleration 9.8 m/s² downward","maximum velocity","acceleration upward"],"answer":1}', '[]', 'Gravity never switches off.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_95eabd63ac5b43', 'subj_phys', 'kinematics', 'Kinematics', 'Describing motion with position, velocity and acceleration.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_535529376717dc', (SELECT id FROM concepts WHERE slug = 'kinematics'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_535529376717dc', (SELECT id FROM formulas WHERE slug = 'kinematic-equations'), 1);

-- Lesson: friction-forces
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_641646cc0a0896', 'friction-forces', 'Friction', 'Model static and kinetic friction with coefficients, decide whether an object starts sliding, and find accelerations with friction.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_9f9ce92f290d0a', 'les_641646cc0a0896', 1, 'Distinguish static friction (up to μₛF_N) from kinetic friction (μₖF_N).');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_b7689652471f22', 'les_641646cc0a0896', 2, 'Decide whether an applied force overcomes static friction.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_fe6742eba47a65', 'les_641646cc0a0896', 3, 'Find acceleration when kinetic friction acts.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_9f9ce92f290d0a', 'les_641646cc0a0896', 'learn', 1, 'definition', '{"term":"Static and kinetic friction","body":"Static friction adjusts to prevent sliding, up to a maximum $f_s \\le \\mu_s F_N$. Once sliding, kinetic friction is $f_k = \\mu_k F_N$, usually with $\\mu_k < \\mu_s$. Both act parallel to the surface, opposing (attempted) sliding."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b7689652471f22', 'les_641646cc0a0896', 'learn', 2, 'worked_example', '{"title":"A 20 kg box on a floor with $\\mu_s = 0.5$, $\\mu_k = 0.3$ is pushed with 120 N","steps":[{"latex":"f_{s,\\max} = 0.5(20)(9.8) = 98\\ \\text{N}","explanation":"120 N > 98 N: it starts to slide."},{"latex":"f_k = 0.3(196) = 58.8\\ \\text{N}","explanation":""},{"latex":"a = \\tfrac{120 - 58.8}{20} \\approx 3.06\\ \\text{m/s}^2","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_fe6742eba47a65', 'les_641646cc0a0896', 'experiment', 3, 'activity', '{"activity":"forces-incline","title":"Friction on a slope"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_478fea934d68d7', 'les_641646cc0a0896', 'learn', 4, 'callout', '{"tone":"tip","title":"Static friction isn''t always maximum","body":"If you push a heavy box with 30 N and it doesn''t move, static friction is exactly 30 N, not $\\mu_s F_N$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_ace1ecf3fdce34', 'les_641646cc0a0896', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Anti-lock brakes keep tires rolling so static friction (larger) acts instead of kinetic friction, shortening stopping distances."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_9f9ce92f290d0a', 'les_641646cc0a0896', 1, 'practice', 'numeric', 1, 'A 50 N push doesn''t move a box. What is the static friction force, in newtons?', '{"answer":50,"unit":"N"}', '[]', 'It matches the push.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_b7689652471f22', 'les_641646cc0a0896', 2, 'practice', 'numeric', 2, 'A 10 kg sled slides on snow with $\mu_k = 0.1$. What is the kinetic friction force, in newtons?', '{"answer":9.8,"tolerance":0.01,"unit":"N"}', '[]', '$0.1 \times 98$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_fe6742eba47a65', 'les_641646cc0a0896', 3, 'practice', 'numeric', 2, 'That sled is pulled horizontally with 30 N. Find its acceleration.', '{"answer":2.02,"tolerance":0.01,"unit":"m/s²"}', '[]', '$\frac{30 - 9.8}{10} = 2.02$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_478fea934d68d7', 'les_641646cc0a0896', 4, 'review', 'multiple_choice', 3, 'A car skids to a stop. Doubling its mass (same tires and road) makes the deceleration…', '{"choices":["half as large","the same","twice as large","four times as large"],"answer":1}', '[]', '$a = \frac{\mu_k mg}{m} = \mu_k g$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_ded4ddbc4c2866', 'subj_phys', 'friction', 'Friction', 'Forces that oppose sliding between surfaces in contact.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_641646cc0a0896', (SELECT id FROM concepts WHERE slug = 'friction'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_641646cc0a0896', (SELECT id FROM formulas WHERE slug = 'kinetic-friction'), 1);

-- Lesson: gravitation-orbits
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_9e1665f8dea309', 'gravitation-orbits', 'Universal gravitation and orbits', 'Use Newton''s law of universal gravitation, explain the value of g at Earth''s surface, and find orbital speeds and periods for circular orbits.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_27ed207cb8f422', 'les_9e1665f8dea309', 1, 'Compute gravitational forces with F = Gm₁m₂/r².');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_b4e9824ddb7db0', 'les_9e1665f8dea309', 2, 'Explain the inverse-square dependence on distance.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_878779d89498bf', 'les_9e1665f8dea309', 3, 'Find orbital speed v = √(GM/r) and period for a circular orbit.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_27ed207cb8f422', 'les_9e1665f8dea309', 'learn', 1, 'definition', '{"term":"Universal gravitation","body":"Every two masses attract with $F = \\frac{Gm_1m_2}{r^2}$, $G = 6.67 \\times 10^{-11}$ N·m²/kg². At Earth''s surface, $g = \\frac{GM_E}{R_E^2} \\approx 9.8$ m/s²."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b4e9824ddb7db0', 'les_9e1665f8dea309', 'learn', 2, 'worked_example', '{"title":"Speed of the International Space Station, 420 km up","steps":[{"latex":"r = 6.371 \\times 10^6 + 4.2 \\times 10^5 = 6.79 \\times 10^6\\ \\text{m}","explanation":"Measured from Earth''s center."},{"latex":"\\tfrac{mv^2}{r} = \\tfrac{GMm}{r^2} \\Rightarrow v = \\sqrt{\\tfrac{GM}{r}} \\approx 7.66\\ \\text{km/s}","explanation":"With $M_E = 5.97 \\times 10^{24}$ kg."},{"latex":"T = \\tfrac{2\\pi r}{v} \\approx 93\\ \\text{min}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_878779d89498bf', 'les_9e1665f8dea309', 'learn', 3, 'callout', '{"tone":"note","title":"Weightlessness","body":"Astronauts on the ISS still have about 90% of their surface weight. They feel weightless because they and the station fall around Earth together."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_3a254452e9caa6', 'les_9e1665f8dea309', 'learn', 4, 'callout', '{"tone":"application","title":"Where this shows up","body":"GPS satellites, weather satellites and the Moon all follow the same rule; geostationary satellites orbit at the one radius where the period is 24 hours."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_27ed207cb8f422', 'les_9e1665f8dea309', 1, 'practice', 'multiple_choice', 1, 'If the distance between two masses triples, the gravitational force becomes…', '{"choices":["1/3 as large","1/9 as large","3 times as large","9 times as large"],"answer":1}', '[]', 'Inverse square.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_b4e9824ddb7db0', 'les_9e1665f8dea309', 2, 'practice', 'numeric', 2, 'Find the gravitational force between two 100 kg masses 1 m apart, in units of $10^{-7}$ N.', '{"answer":6.67,"tolerance":0.01}', '[]', '$6.67 \times 10^{-11} \times 10^4 = 6.67 \times 10^{-7}$ N.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_878779d89498bf', 'les_9e1665f8dea309', 3, 'practice', 'multiple_choice', 2, 'A satellite in a lower circular orbit moves…', '{"choices":["slower","faster","at the same speed","backward"],"answer":1}', '[]', '$v = \sqrt{GM/r}$ grows as $r$ shrinks.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_3a254452e9caa6', 'les_9e1665f8dea309', 4, 'review', 'multiple_choice', 3, 'On a planet with twice Earth''s mass and twice its radius, surface gravity is…', '{"choices":["2g","g","g/2","4g"],"answer":2}', '[]', '$\frac{2}{2^2} = \frac{1}{2}$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_1580b44a9ad0c5', 'subj_phys', 'circular-motion', 'Circular motion and gravitation', 'Motion in circles, centripetal force and universal gravitation.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_9e1665f8dea309', (SELECT id FROM concepts WHERE slug = 'circular-motion'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_9e1665f8dea309', (SELECT id FROM formulas WHERE slug = 'universal-gravitation'), 1);
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_9e1665f8dea309', (SELECT id FROM formulas WHERE slug = 'centripetal-acceleration'), 2);

-- Lesson: kinetic-potential-energy
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_5d916184c675b3', 'kinetic-potential-energy', 'Kinetic and potential energy', 'Compute kinetic energy ½mv², gravitational potential energy mgh and elastic potential energy ½kx², and use the work–energy theorem.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_eab78dbaf2202d', 'les_5d916184c675b3', 1, 'Compute KE, gravitational PE and elastic PE with units.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_145cd70ce254ba', 'les_5d916184c675b3', 2, 'Apply the work–energy theorem W_net = ΔKE.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_5b03b47bdef240', 'les_5d916184c675b3', 3, 'Explain that potential energy depends on a chosen reference level.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_eab78dbaf2202d', 'les_5d916184c675b3', 'learn', 1, 'definition', '{"term":"Forms of mechanical energy","body":"Kinetic: $KE = \\frac{1}{2}mv^2$. Gravitational potential (near Earth): $PE_g = mgh$, with $h$ measured from a reference level you choose. Elastic: $PE_s = \\frac{1}{2}kx^2$ for a spring stretched or compressed by $x$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_145cd70ce254ba', 'les_5d916184c675b3', 'learn', 2, 'worked_example', '{"title":"Energies","steps":[{"latex":"KE = \\tfrac{1}{2}(1000)(20)^2 = 200{,}000\\ \\text{J}","explanation":"A car at 20 m/s."},{"latex":"PE_g = 2(9.8)(5) = 98\\ \\text{J}","explanation":"A 2 kg book on a 5 m shelf."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_5b03b47bdef240', 'les_5d916184c675b3', 'learn', 3, 'definition', '{"term":"Work–energy theorem","body":"The net work done on an object equals its change in kinetic energy: $W_{\\text{net}} = \\Delta KE$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_af31c24706b61c', 'les_5d916184c675b3', 'learn', 4, 'worked_example', '{"title":"A net 600 N force acts on a 75 kg sprinter over 5 m from rest","steps":[{"latex":"\\tfrac{1}{2}(75)v^2 = 600(5) = 3000\\ \\text{J}","explanation":""},{"latex":"v \\approx 8.94\\ \\text{m/s}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_6b8bc9c9f2509f', 'les_5d916184c675b3', 'experiment', 5, 'activity', '{"activity":"spring-oscillator","title":"Kinetic and elastic energy trade places"}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_264c3ba9d7fa25', 'les_5d916184c675b3', 'learn', 6, 'callout', '{"tone":"application","title":"Where this shows up","body":"Car crash energy scales with $v^2$: hitting a wall at 100 km/h involves four times the energy of 50 km/h, which is why crumple zones and speed limits matter."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_eab78dbaf2202d', 'les_5d916184c675b3', 1, 'practice', 'numeric', 1, 'Find the kinetic energy of a 0.15 kg ball at 40 m/s, in joules.', '{"answer":120,"unit":"J"}', '[]', '$\frac{1}{2}(0.15)(1600)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_145cd70ce254ba', 'les_5d916184c675b3', 2, 'practice', 'numeric', 2, 'A spring with $k = 400$ N/m is compressed 0.1 m. Find its elastic PE, in joules.', '{"answer":2,"unit":"J"}', '[]', '$\frac{1}{2}(400)(0.01)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_5b03b47bdef240', 'les_5d916184c675b3', 3, 'practice', 'multiple_choice', 2, 'If a car''s speed triples, its kinetic energy…', '{"choices":["triples","becomes 6 times as large","becomes 9 times as large","stays the same"],"answer":2}', '[]', '$KE \propto v^2$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_af31c24706b61c', 'les_5d916184c675b3', 4, 'review', 'numeric', 3, 'A 2 kg cart at 3 m/s has 16 J of net work done on it. Find its new speed, in m/s.', '{"answer":5,"unit":"m/s"}', '[]', '$9 + 16 = 25 = \frac{1}{2}(2)v^2$, $v = 5$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_173d9168467e6c', 'subj_phys', 'energy', 'Work and energy', 'Work, kinetic and potential energy, conservation of energy and power.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_5d916184c675b3', (SELECT id FROM concepts WHERE slug = 'energy'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_5d916184c675b3', (SELECT id FROM formulas WHERE slug = 'kinetic-energy'), 1);
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_5d916184c675b3', (SELECT id FROM formulas WHERE slug = 'work-energy'), 2);
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_5d916184c675b3', (SELECT id FROM formulas WHERE slug = 'spring-potential-energy'), 3);

-- Lesson: momentum-conservation
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_9bf619ed6fe18a', 'momentum-conservation', 'Conservation of momentum in collisions', 'Use conservation of momentum to analyze collisions and explosions, and classify collisions as elastic or inelastic by what happens to kinetic energy.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_e3cd83d48c6338', 'les_9bf619ed6fe18a', 1, 'Apply total momentum before = total momentum after for an isolated system.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_f9057008d9c1aa', 'les_9bf619ed6fe18a', 2, 'Solve perfectly inelastic collisions and recoil problems.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_f8651f898d9d82', 'les_9bf619ed6fe18a', 3, 'Compare kinetic energy before and after to classify collisions.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e3cd83d48c6338', 'les_9bf619ed6fe18a', 'learn', 1, 'definition', '{"term":"Conservation of momentum","body":"If no external net force acts on a system, its total momentum is constant: $m_1v_1 + m_2v_2 = m_1v_1'' + m_2v_2''$. This follows from Newton''s third law: the objects exert equal and opposite impulses on each other."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f9057008d9c1aa', 'les_9bf619ed6fe18a', 'learn', 2, 'worked_example', '{"title":"A 2 kg cart at 3 m/s hits a 1 kg cart at rest; they stick together","steps":[{"latex":"2(3) + 1(0) = (3)v'' \\Rightarrow v'' = 2\\ \\text{m/s}","explanation":""},{"latex":"KE: 9\\ \\text{J before},\\ 6\\ \\text{J after}","explanation":"Perfectly inelastic: 3 J became heat and sound."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_f8651f898d9d82', 'les_9bf619ed6fe18a', 'learn', 3, 'worked_example', '{"title":"Recoil: a 4 kg rifle fires a 0.01 kg bullet at 400 m/s","steps":[{"latex":"0 = 0.01(400) + 4v_r \\Rightarrow v_r = -1\\ \\text{m/s}","explanation":"The rifle moves backward."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7293793310aac9', 'les_9bf619ed6fe18a', 'learn', 4, 'definition', '{"term":"Collision types","body":"Elastic: kinetic energy is conserved (billiard balls, approximately). Inelastic: some KE becomes other forms. Perfectly inelastic: the objects stick together. Momentum is conserved in all three."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_508fbf1547f95d', 'les_9bf619ed6fe18a', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Crash investigators use momentum conservation to work out cars'' speeds before a collision from where the wreckage ended up."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_e3cd83d48c6338', 'les_9bf619ed6fe18a', 1, 'practice', 'numeric', 1, 'A 60 kg skater at rest pushes a 40 kg skater, who moves off at 3 m/s. Find the first skater''s speed.', '{"answer":2,"unit":"m/s"}', '[]', '$60v = 40(3)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_f9057008d9c1aa', 'les_9bf619ed6fe18a', 2, 'practice', 'numeric', 2, 'A 1500 kg car at 20 m/s rear-ends a 1000 kg car at 10 m/s; they lock together. Find their speed.', '{"answer":16,"unit":"m/s"}', '[]', '$\frac{30000 + 10000}{2500} = 16$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_f8651f898d9d82', 'les_9bf619ed6fe18a', 3, 'practice', 'multiple_choice', 2, 'In which collision is kinetic energy conserved?', '{"choices":["Perfectly inelastic","Elastic","Any collision","None"],"answer":1}', '[]', 'That''s the definition of elastic.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_7293793310aac9', 'les_9bf619ed6fe18a', 4, 'review', 'multiple_choice', 3, 'Two equal masses collide head-on elastically, one moving at 5 m/s and the other at rest. Afterward…', '{"choices":["both move at 2.5 m/s","the first stops and the second moves at 5 m/s","both stop","the first bounces back at 5 m/s"],"answer":1}', '[]', 'Equal masses exchange velocities in an elastic head-on collision (Newton''s cradle).');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_503c4af7903cab', 'subj_phys', 'momentum', 'Momentum', 'Mass times velocity; conserved in isolated systems.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_9bf619ed6fe18a', (SELECT id FROM concepts WHERE slug = 'momentum'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_9bf619ed6fe18a', (SELECT id FROM formulas WHERE slug = 'momentum-impulse'), 1);

-- Lesson: momentum-impulse
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_b0592d6f1798da', 'momentum-impulse', 'Momentum and impulse', 'Define momentum p = mv, relate force and time to change in momentum through impulse, and explain how increasing collision time reduces force.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_b66ff83f0159c9', 'les_b0592d6f1798da', 1, 'Compute momentum as a vector with sign.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_10403488116a4d', 'les_b0592d6f1798da', 2, 'Apply J = FΔt = Δp.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_e5715446f21fcc', 'les_b0592d6f1798da', 3, 'Explain safety designs that extend collision time.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_b66ff83f0159c9', 'les_b0592d6f1798da', 'learn', 1, 'definition', '{"term":"Momentum and impulse","body":"Momentum $\\vec{p} = m\\vec{v}$ (kg·m/s). Impulse $\\vec{J} = \\vec{F}_{\\text{avg}}\\Delta t$ (N·s) equals the change in momentum: $\\vec{J} = \\Delta\\vec{p}$. This is Newton''s second law rewritten."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_10403488116a4d', 'les_b0592d6f1798da', 'learn', 2, 'worked_example', '{"title":"A 0.15 kg baseball at 40 m/s is caught and stopped in 0.01 s","steps":[{"latex":"\\Delta p = 0 - 0.15(40) = -6\\ \\text{kg·m/s}","explanation":""},{"latex":"F = \\tfrac{-6}{0.01} = -600\\ \\text{N}","explanation":"Pulling the glove back (longer time) lowers the force."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_e5715446f21fcc', 'les_b0592d6f1798da', 'learn', 3, 'worked_example', '{"title":"The same ball bounces off a wall at 40 m/s back","steps":[{"latex":"\\Delta p = 0.15(-40) - 0.15(40) = -12\\ \\text{kg·m/s}","explanation":"Bouncing doubles the impulse."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_90af47628baf93', 'les_b0592d6f1798da', 'learn', 4, 'callout', '{"tone":"application","title":"Where this shows up","body":"Airbags, crumple zones, helmets and gym mats all extend the stopping time, so the same change in momentum happens with a smaller force."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_b66ff83f0159c9', 'les_b0592d6f1798da', 1, 'practice', 'numeric', 1, 'Find the momentum of a 1200 kg car at 15 m/s, in kg·m/s.', '{"answer":18000,"unit":"kg·m/s"}', '[]', '$1200 \times 15$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_10403488116a4d', 'les_b0592d6f1798da', 2, 'practice', 'numeric', 2, 'A 0.5 kg ball''s velocity changes from 6 m/s to −4 m/s. Find the impulse, in N·s.', '{"answer":-5,"unit":"N·s"}', '[]', '$0.5(-4 - 6)$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_e5715446f21fcc', 'les_b0592d6f1798da', 3, 'practice', 'numeric', 2, 'A 2000 N force acts on a 1000 kg car for 3 s from rest. Find its final speed.', '{"answer":6,"unit":"m/s"}', '[]', '$\Delta p = 6000$, so $v = 6$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_90af47628baf93', 'les_b0592d6f1798da', 4, 'review', 'multiple_choice', 3, 'Why do you bend your knees when landing from a jump?', '{"choices":["To reduce your momentum change","To increase the stopping time and reduce the force","To increase the impulse","To lower your mass"],"answer":1}', '[]', 'Same impulse over a longer time means less force.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_503c4af7903cab', 'subj_phys', 'momentum', 'Momentum', 'Mass times velocity; conserved in isolated systems.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_b0592d6f1798da', (SELECT id FROM concepts WHERE slug = 'momentum'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_b0592d6f1798da', (SELECT id FROM formulas WHERE slug = 'momentum-impulse'), 1);

-- Lesson: newtons-first-law
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_ed2e1b47055aa2', 'newtons-first-law', 'Newton''s first law and inertia', 'Understand that objects keep their velocity unless a net force acts, connect inertia to mass, and analyze objects in equilibrium.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_52b68f12957060', 'les_ed2e1b47055aa2', 1, 'State Newton''s first law.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_75990771e0ad73', 'les_ed2e1b47055aa2', 2, 'Explain inertia and its connection to mass.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_c61225d34ff345', 'les_ed2e1b47055aa2', 3, 'Use the equilibrium condition ΣF = 0 to find an unknown force.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_52b68f12957060', 'les_ed2e1b47055aa2', 'learn', 1, 'definition', '{"term":"First law","body":"An object at rest stays at rest, and an object in motion keeps moving at constant velocity, unless acted on by a nonzero net force. Motion doesn''t need a force; changes in motion do."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_75990771e0ad73', 'les_ed2e1b47055aa2', 'learn', 2, 'definition', '{"term":"Inertia and equilibrium","body":"Inertia is the tendency to resist changes in velocity; mass measures it. An object with zero net force (at rest or at constant velocity) is in equilibrium: $\\sum \\vec{F} = 0$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_c61225d34ff345', 'les_ed2e1b47055aa2', 'learn', 3, 'worked_example', '{"title":"A crate slides at constant velocity while pushed with 120 N. How large is the friction force?","steps":[{"latex":"\\text{constant velocity} \\Rightarrow \\sum F = 0","explanation":""},{"latex":"f = 120\\ \\text{N, opposite the push}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_224787ecfe033d', 'les_ed2e1b47055aa2', 'learn', 4, 'callout', '{"tone":"warning","title":"A common misconception","body":"A hockey puck gliding across ice doesn''t need a force to keep moving; it slows only because of a little friction. The ancient idea that motion needs a constant push is wrong."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_28dedd755dad10', 'les_ed2e1b47055aa2', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Seat belts exist because of inertia: in a sudden stop, your body keeps moving forward until a force (the belt, ideally) stops it."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_52b68f12957060', 'les_ed2e1b47055aa2', 1, 'practice', 'multiple_choice', 1, 'A spacecraft far from any star or planet turns off its engines. It will…', '{"choices":["slow down and stop","keep moving at constant velocity","speed up","fall"],"answer":1}', '[]', 'No net force, no change in velocity.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_75990771e0ad73', 'les_ed2e1b47055aa2', 2, 'practice', 'numeric', 2, 'A lamp hangs at rest from a cord. Its weight is 30 N. What is the tension in the cord, in newtons?', '{"answer":30,"unit":"N"}', '[]', 'Equilibrium: tension balances weight.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_c61225d34ff345', 'les_ed2e1b47055aa2', 3, 'practice', 'multiple_choice', 2, 'Which has more inertia?', '{"choices":["A 2 kg ball moving fast","A 10 kg ball at rest","They''re equal","Depends on speed"],"answer":1}', '[]', 'Inertia depends only on mass.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_224787ecfe033d', 'les_ed2e1b47055aa2', 4, 'review', 'multiple_choice', 3, 'A car moves at a constant 25 m/s on a straight highway. The net force on it is…', '{"choices":["forward","backward","zero","equal to its weight"],"answer":2}', '[]', 'Constant velocity means equilibrium; engine force balances drag and friction.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_ed2e1b47055aa2', (SELECT id FROM concepts WHERE slug = 'newtons-laws'));

-- Lesson: newtons-third-law
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_ee263db3836834', 'newtons-third-law', 'Newton''s third law', 'Identify action–reaction pairs: equal and opposite forces that act on different objects, and explain why they don''t cancel.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_123cfbfda5ce38', 'les_ee263db3836834', 1, 'State Newton''s third law.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_8d42c604ed55c4', 'les_ee263db3836834', 2, 'Identify both forces in an interaction pair.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_1500b62be631f8', 'les_ee263db3836834', 3, 'Explain why third-law pairs never cancel each other.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_123cfbfda5ce38', 'les_ee263db3836834', 'learn', 1, 'definition', '{"term":"Third law","body":"If object A exerts a force on object B, then B exerts a force on A that is equal in size and opposite in direction. The two forces act on different objects and are the same type (both contact, both gravitational, …)."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_8d42c604ed55c4', 'les_ee263db3836834', 'learn', 2, 'worked_example', '{"title":"You push on a wall with 50 N","steps":[{"latex":"\\text{wall on you: 50 N, toward you}","explanation":"The pair to your push."},{"latex":"\\text{you don''t move because friction from the floor also acts on you}","explanation":"Forces on you are what decide your motion."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_1500b62be631f8', 'les_ee263db3836834', 'learn', 3, 'worked_example', '{"title":"A horse pulls a cart. If the cart pulls back equally, how does anything move?","steps":[{"latex":"\\text{the cart moves if the horse''s pull exceeds friction on the cart}","explanation":"Only forces on the cart matter for the cart."},{"latex":"\\text{the horse moves because the ground pushes it forward harder than the cart pulls back}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_96559b62e4d37e', 'les_ee263db3836834', 'learn', 4, 'callout', '{"tone":"application","title":"Where this shows up","body":"Rockets push exhaust gas backward, and the gas pushes the rocket forward; no air is needed, which is why rockets work in space."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_123cfbfda5ce38', 'les_ee263db3836834', 1, 'practice', 'multiple_choice', 1, 'Earth pulls a falling apple down with 1 N. The reaction force is…', '{"choices":["the air pushing up on the apple","the apple pulling Earth up with 1 N","the ground pushing the apple","zero"],"answer":1}', '[]', 'Same type (gravity), opposite object.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_8d42c604ed55c4', 'les_ee263db3836834', 2, 'practice', 'multiple_choice', 2, 'A truck and a small car collide. During the collision, the force on the car is…', '{"choices":["greater than on the truck","smaller than on the truck","equal in size to the force on the truck","zero"],"answer":2}', '[]', 'Third law. The car accelerates more because its mass is smaller.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_1500b62be631f8', 'les_ee263db3836834', 3, 'practice', 'multiple_choice', 2, 'A book rests on a table. The third-law partner of the book''s weight is…', '{"choices":["the table pushing up on the book","the book pulling Earth up","the table''s weight","friction"],"answer":1}', '[]', 'The normal force balances the weight but isn''t its third-law pair.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_96559b62e4d37e', 'les_ee263db3836834', 4, 'review', 'multiple_choice', 3, 'Why don''t third-law pairs cancel?', '{"choices":["They aren''t equal","They act on different objects","They act at different times","They do cancel"],"answer":1}', '[]', 'Only forces on the same object add up to a net force.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_ee263db3836834', (SELECT id FROM concepts WHERE slug = 'newtons-laws'));

-- Lesson: position-velocity
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_1021818f9255ae', 'position-velocity', 'Position, displacement and velocity', 'Describe one-dimensional motion with position and displacement, compute average velocity and average speed, and read velocity from the slope of a position-time graph.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_02ce26fd22ab20', 'les_1021818f9255ae', 1, 'Define position relative to an origin and displacement as change in position.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_897a8717acfa9f', 'les_1021818f9255ae', 2, 'Compute average velocity Δx/Δt and average speed (distance/time).');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_593075af3c184b', 'les_1021818f9255ae', 3, 'Interpret slope on a position-time graph as velocity.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_02ce26fd22ab20', 'les_1021818f9255ae', 'learn', 1, 'definition', '{"term":"Velocity","body":"Average velocity $= \\frac{\\Delta x}{\\Delta t}$, a vector (its sign gives direction). Average speed $= \\frac{\\text{distance}}{\\Delta t}$, a scalar. Instantaneous velocity is the slope of the position-time graph at a moment."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_897a8717acfa9f', 'les_1021818f9255ae', 'learn', 2, 'worked_example', '{"title":"A runner completes one 400 m lap in 80 s","steps":[{"latex":"\\text{average speed} = \\tfrac{400}{80} = 5\\ \\text{m/s}","explanation":""},{"latex":"\\text{average velocity} = \\tfrac{0}{80} = 0","explanation":"Back at the start."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_593075af3c184b', 'les_1021818f9255ae', 'experiment', 3, 'activity', '{"activity":"motion-graphs","title":"Slope of x–t is velocity","params":{"v0":4,"a":0,"x0":-10,"t":3}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_2ca885d38508b3', 'les_1021818f9255ae', 'experiment', 4, 'callout', '{"tone":"tip","title":"Try this","body":"With $a = 0$, the position graph is a straight line whose slope equals the velocity you set. Make $v_0$ negative and the line slopes down."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7b51d8a55d9310', 'les_1021818f9255ae', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Speed cameras that time cars between two points measure average speed; radar guns measure instantaneous speed."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_02ce26fd22ab20', 'les_1021818f9255ae', 1, 'practice', 'numeric', 1, 'A cyclist moves from $x = 20$ m to $x = 80$ m in 12 s. Find the average velocity.', '{"answer":5,"unit":"m/s"}', '[]', '$\frac{60}{12}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_897a8717acfa9f', 'les_1021818f9255ae', 2, 'practice', 'numeric', 2, 'A car drives 30 km east in 0.5 h, then 10 km west in 0.25 h. Find its average velocity in km/h (east positive).', '{"answer":26.67,"tolerance":0.02,"unit":"km/h"}', '[]', '$\frac{20}{0.75} \approx 26.67$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_593075af3c184b', 'les_1021818f9255ae', 3, 'practice', 'numeric', 2, 'For that trip, find the average speed in km/h.', '{"answer":53.33,"tolerance":0.02,"unit":"km/h"}', '[]', '$\frac{40}{0.75} \approx 53.33$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_2ca885d38508b3', 'les_1021818f9255ae', 4, 'review', 'multiple_choice', 3, 'A position-time graph is a horizontal line. The object is…', '{"choices":["moving at constant speed","at rest","accelerating","moving backward"],"answer":1}', '[]', 'Zero slope: zero velocity.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_95eabd63ac5b43', 'subj_phys', 'kinematics', 'Kinematics', 'Describing motion with position, velocity and acceleration.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_1021818f9255ae', (SELECT id FROM concepts WHERE slug = 'kinematics'));

-- Lesson: power-physics
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_76e79e52f51875', 'power-physics', 'Power', 'Define power as the rate of doing work, compute it in watts with P = W/t and P = Fv, and relate it to everyday ratings.', 20, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_d224e3a9bde590', 'les_76e79e52f51875', 1, 'Compute P = W/t in watts.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_7fc65577baac9d', 'les_76e79e52f51875', 2, 'Use P = Fv for a constant force at constant speed.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_8e2056a32a6917', 'les_76e79e52f51875', 3, 'Convert between watts, kilowatts and horsepower.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_d224e3a9bde590', 'les_76e79e52f51875', 'learn', 1, 'definition', '{"term":"Power","body":"Power is the rate of energy transfer: $P = \\frac{W}{t}$, in watts (1 W = 1 J/s). For a force $F$ moving something at speed $v$ along the force, $P = Fv$. 1 horsepower ≈ 746 W."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7fc65577baac9d', 'les_76e79e52f51875', 'learn', 2, 'worked_example', '{"title":"Lifting a 50 kg crate 3 m in 2 s","steps":[{"latex":"W = 50(9.8)(3) = 1470\\ \\text{J}","explanation":""},{"latex":"P = \\tfrac{1470}{2} = 735\\ \\text{W}","explanation":"About 1 horsepower."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_8e2056a32a6917', 'les_76e79e52f51875', 'learn', 3, 'worked_example', '{"title":"A car''s engine pushes with 2000 N at 25 m/s","steps":[{"latex":"P = 2000(25) = 50{,}000\\ \\text{W} = 50\\ \\text{kW}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0a5a565a49bd3b', 'les_76e79e52f51875', 'learn', 4, 'callout', '{"tone":"application","title":"Where this shows up","body":"Electricity bills charge for energy in kilowatt-hours: a 1000 W heater running for 1 hour uses 1 kWh = 3.6 million joules."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_d224e3a9bde590', 'les_76e79e52f51875', 1, 'practice', 'numeric', 1, 'A motor does 6000 J of work in 20 s. Find its power, in watts.', '{"answer":300,"unit":"W"}', '[]', '$\frac{6000}{20}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_7fc65577baac9d', 'les_76e79e52f51875', 2, 'practice', 'numeric', 2, 'A 60 kg student climbs 4 m of stairs in 5 s. Find her power, in watts, to one decimal place.', '{"answer":470.4,"tolerance":0.1,"unit":"W"}', '[]', '$\frac{60(9.8)(4)}{5} = 470.4$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_8e2056a32a6917', 'les_76e79e52f51875', 3, 'practice', 'numeric', 2, 'How much energy, in kWh, does a 1500 W hair dryer use in 10 minutes?', '{"answer":0.25,"tolerance":0.001,"unit":"kWh"}', '[]', '$1.5\ \text{kW} \times \frac{1}{6}$ h.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_0a5a565a49bd3b', 'les_76e79e52f51875', 4, 'review', 'multiple_choice', 3, 'Two cranes lift identical loads to the same height; crane A takes half the time. Crane A…', '{"choices":["does twice the work","has twice the power","does half the work","has half the power"],"answer":1}', '[]', 'Same work, half the time.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_173d9168467e6c', 'subj_phys', 'energy', 'Work and energy', 'Work, kinetic and potential energy, conservation of energy and power.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_76e79e52f51875', (SELECT id FROM concepts WHERE slug = 'energy'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_76e79e52f51875', (SELECT id FROM formulas WHERE slug = 'work-energy'), 1);

-- Lesson: scalars-vectors
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_b5e3cc2a7be2c6', 'scalars-vectors', 'Scalars and vectors', 'Distinguish scalar quantities (magnitude only) from vectors (magnitude and direction), and add perpendicular vectors with the Pythagorean theorem.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_545f55d0039cc6', 'les_b5e3cc2a7be2c6', 1, 'Classify quantities as scalars or vectors.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_bd5b12379a1db3', 'les_b5e3cc2a7be2c6', 2, 'Distinguish distance from displacement and speed from velocity.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_0df2d08b00c9fe', 'les_b5e3cc2a7be2c6', 3, 'Add vectors tip to tail and find the magnitude and direction of a resultant.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_545f55d0039cc6', 'les_b5e3cc2a7be2c6', 'learn', 1, 'definition', '{"term":"Scalars and vectors","body":"A scalar has only size (mass, time, distance, speed, energy). A vector has size and direction (displacement, velocity, acceleration, force). Vectors are drawn as arrows."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_bd5b12379a1db3', 'les_b5e3cc2a7be2c6', 'learn', 2, 'worked_example', '{"title":"Walk 3 m east, then 4 m north","steps":[{"latex":"\\text{distance} = 3 + 4 = 7\\ \\text{m}","explanation":"Scalar: total path length."},{"latex":"|\\text{displacement}| = \\sqrt{3^2 + 4^2} = 5\\ \\text{m}","explanation":"Tip-to-tail addition."},{"latex":"\\theta = \\tan^{-1}\\tfrac{4}{3} \\approx 53.1° \\text{ north of east}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_0df2d08b00c9fe', 'les_b5e3cc2a7be2c6', 'experiment', 3, 'activity', '{"activity":"vectors","title":"Add displacements tip to tail","params":{"ux":3,"uy":0,"vx":0,"vy":4}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_1ddcf921896c36', 'les_b5e3cc2a7be2c6', 'learn', 4, 'callout', '{"tone":"application","title":"Where this shows up","body":"Pilots add the airplane''s velocity relative to the air and the wind''s velocity to find their actual ground velocity, a vector sum."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_545f55d0039cc6', 'les_b5e3cc2a7be2c6', 1, 'practice', 'multiple_choice', 1, 'Which is a vector?', '{"choices":["Mass","Temperature","Velocity","Energy"],"answer":2}', '[]', 'Velocity has a direction.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_bd5b12379a1db3', 'les_b5e3cc2a7be2c6', 2, 'practice', 'numeric', 2, 'A runner goes 6 m west, then 8 m south. What is the magnitude of the displacement?', '{"answer":10,"unit":"m"}', '[]', '$\sqrt{36 + 64} = 10$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_0df2d08b00c9fe', 'les_b5e3cc2a7be2c6', 3, 'practice', 'numeric', 2, 'For that trip, what distance was traveled?', '{"answer":14,"unit":"m"}', '[]', '$6 + 8 = 14$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_1ddcf921896c36', 'les_b5e3cc2a7be2c6', 4, 'review', 'multiple_choice', 3, 'A car drives once around a circular track and returns to start. Which is zero?', '{"choices":["Distance","Average speed","Displacement","Time"],"answer":2}', '[]', 'It ends where it started.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_b5e3cc2a7be2c6', (SELECT id FROM concepts WHERE slug = 'vectors'));

-- Lesson: uniform-circular-motion
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_868def0fc96ce1', 'uniform-circular-motion', 'Uniform circular motion', 'Explain why motion in a circle at constant speed is accelerated, compute centripetal acceleration and force, and identify which real force provides it.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_463461568e844b', 'les_868def0fc96ce1', 1, 'Compute v = 2πr/T and a_c = v²/r.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_5e7d334626b416', 'les_868def0fc96ce1', 2, 'Explain that the net force points toward the center.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_65145d01b689ba', 'les_868def0fc96ce1', 3, 'Identify the force supplying the centripetal force (tension, friction, gravity, normal force).');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_463461568e844b', 'les_868def0fc96ce1', 'learn', 1, 'definition', '{"term":"Centripetal acceleration","body":"At constant speed in a circle, velocity keeps changing direction, so the object accelerates toward the center: $a_c = \\frac{v^2}{r}$. By Newton''s second law the net force is also inward: $F_c = \\frac{mv^2}{r}$."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_5e7d334626b416', 'les_868def0fc96ce1', 'learn', 2, 'worked_example', '{"title":"A 1000 kg car rounds a curve of radius 50 m at 20 m/s","steps":[{"latex":"a_c = \\tfrac{20^2}{50} = 8\\ \\text{m/s}^2","explanation":""},{"latex":"F_c = 1000(8) = 8000\\ \\text{N}","explanation":"Supplied by friction between tires and road."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_65145d01b689ba', 'les_868def0fc96ce1', 'learn', 3, 'worked_example', '{"title":"A 0.5 kg ball on a 1.2 m string makes one turn every 0.8 s","steps":[{"latex":"v = \\tfrac{2\\pi(1.2)}{0.8} \\approx 9.42\\ \\text{m/s}","explanation":""},{"latex":"T_{\\text{string}} = \\tfrac{0.5(9.42)^2}{1.2} \\approx 37\\ \\text{N}","explanation":"Ignoring gravity''s small effect."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7bf3d0f434f780', 'les_868def0fc96ce1', 'learn', 4, 'callout', '{"tone":"warning","title":"No outward force","body":"\"Centrifugal force\" isn''t a real force on the object. If the string breaks, the ball flies off along the tangent, not outward along the radius."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_2052c8b18af16d', 'les_868def0fc96ce1', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Highway curves are banked and given speed limits so that friction plus the tilted normal force can supply $\\frac{mv^2}{r}$; centrifuges spin samples to separate them."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_463461568e844b', 'les_868def0fc96ce1', 1, 'practice', 'numeric', 1, 'Find the centripetal acceleration of a point moving at 6 m/s on a circle of radius 3 m.', '{"answer":12,"unit":"m/s²"}', '[]', '$\frac{36}{3}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_5e7d334626b416', 'les_868def0fc96ce1', 2, 'practice', 'multiple_choice', 2, 'If the speed doubles on the same circle, the centripetal force…', '{"choices":["doubles","quadruples","halves","stays the same"],"answer":1}', '[]', '$F \propto v^2$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_65145d01b689ba', 'les_868def0fc96ce1', 3, 'practice', 'numeric', 2, 'A 0.2 kg stone whirls at 5 m/s on a 0.5 m string (horizontal circle). Find the tension, in newtons.', '{"answer":10,"unit":"N"}', '[]', '$\frac{0.2 \cdot 25}{0.5}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_7bf3d0f434f780', 'les_868def0fc96ce1', 4, 'review', 'multiple_choice', 3, 'What supplies the centripetal force for the Moon orbiting Earth?', '{"choices":["Tension","Friction","Earth''s gravity","The Moon''s inertia"],"answer":2}', '[]', 'Gravity points toward Earth''s center.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_1580b44a9ad0c5', 'subj_phys', 'circular-motion', 'Circular motion and gravitation', 'Motion in circles, centripetal force and universal gravitation.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_868def0fc96ce1', (SELECT id FROM concepts WHERE slug = 'circular-motion'));
INSERT OR IGNORE INTO lesson_formulas (lesson_id, formula_id, position) VALUES ('les_868def0fc96ce1', (SELECT id FROM formulas WHERE slug = 'centripetal-acceleration'), 1);

-- Lesson: units-sig-figs
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_05f115d0b43124', 'units-sig-figs', 'Units, measurement and significant figures', 'Use SI base units and prefixes, convert units with conversion factors, and report results with a sensible number of significant figures.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_03562916dedf0c', 'les_05f115d0b43124', 1, 'Name the SI base units for length, mass and time, and use metric prefixes.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_6e2f29400d696c', 'les_05f115d0b43124', 2, 'Convert units by multiplying by conversion factors equal to 1.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_bfbb17bdb06477', 'les_05f115d0b43124', 3, 'Count significant figures and round calculated results appropriately.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_03562916dedf0c', 'les_05f115d0b43124', 'learn', 1, 'definition', '{"term":"SI units","body":"Length: meter (m). Mass: kilogram (kg). Time: second (s). Prefixes scale by powers of ten: kilo ($10^3$), centi ($10^{-2}$), milli ($10^{-3}$), micro ($10^{-6}$), nano ($10^{-9}$)."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_6e2f29400d696c', 'les_05f115d0b43124', 'learn', 2, 'worked_example', '{"title":"Convert 72 km/h to m/s","steps":[{"latex":"72\\,\\tfrac{\\text{km}}{\\text{h}} \\times \\tfrac{1000\\ \\text{m}}{1\\ \\text{km}} \\times \\tfrac{1\\ \\text{h}}{3600\\ \\text{s}}","explanation":"Each factor equals 1; units cancel."},{"latex":"= 20\\ \\text{m/s}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_bfbb17bdb06477', 'les_05f115d0b43124', 'learn', 3, 'definition', '{"term":"Significant figures","body":"Nonzero digits count; zeros between them count; leading zeros don''t; trailing zeros after a decimal point do. Multiply or divide: keep the fewest significant figures of the inputs. Add or subtract: keep the fewest decimal places."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_add920c7f5d0f2', 'les_05f115d0b43124', 'learn', 4, 'worked_example', '{"title":"$2.5 \\times 3.42$","steps":[{"latex":"8.55 \\to 8.6","explanation":"2.5 has two significant figures, so the answer gets two."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_7b9fffc7811284', 'les_05f115d0b43124', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"In 1999 NASA lost the Mars Climate Orbiter because one team used pound-seconds and another newton-seconds. Writing units at every step catches such errors."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_03562916dedf0c', 'les_05f115d0b43124', 1, 'practice', 'numeric', 1, 'Convert 90 km/h to m/s.', '{"answer":25,"unit":"m/s"}', '[]', '$90 \times \frac{1000}{3600} = 25$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_6e2f29400d696c', 'les_05f115d0b43124', 2, 'practice', 'multiple_choice', 1, 'How many significant figures are in 0.00450?', '{"choices":["2","3","5","6"],"answer":1}', '[]', 'Leading zeros don''t count; the trailing zero after the decimal does: 4, 5, 0.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_bfbb17bdb06477', 'les_05f115d0b43124', 3, 'practice', 'numeric', 2, 'Convert 2.5 mm to meters.', '{"answer":0.0025,"tolerance":0.00001,"unit":"m"}', '[]', '$2.5 \times 10^{-3}$ m.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_add920c7f5d0f2', 'les_05f115d0b43124', 4, 'review', 'multiple_choice', 3, 'Report $12.11 + 0.3$ correctly.', '{"choices":["12.41","12.4","12","12.410"],"answer":1}', '[]', 'Fewest decimal places: one.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_e382b1ded37d26', 'subj_phys', 'measurement', 'Measurement and units', 'Expressing physical quantities with SI units, prefixes and appropriate precision.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_05f115d0b43124', (SELECT id FROM concepts WHERE slug = 'measurement'));

-- Lesson: vector-components-physics
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_ac2e54dd59fd87', 'vector-components-physics', 'Vector components', 'Resolve vectors into perpendicular components with sine and cosine, and rebuild a resultant from components to find its magnitude and direction.', 30, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_6ec1f29f8ec671', 'les_ac2e54dd59fd87', 1, 'Resolve a vector: Aₓ = A cos θ, A_y = A sin θ.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_aee7c08db59708', 'les_ac2e54dd59fd87', 2, 'Add vectors by adding components.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_a95bb0ace308ec', 'les_ac2e54dd59fd87', 3, 'Find magnitude and direction from components.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_6ec1f29f8ec671', 'les_ac2e54dd59fd87', 'learn', 1, 'definition', '{"term":"Components","body":"A vector of size $A$ at angle $\\theta$ above the $+x$-axis has $A_x = A\\cos\\theta$ and $A_y = A\\sin\\theta$. Going back: $A = \\sqrt{A_x^2 + A_y^2}$, $\\theta = \\tan^{-1}\\frac{A_y}{A_x}$ (check the quadrant)."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_aee7c08db59708', 'les_ac2e54dd59fd87', 'learn', 2, 'worked_example', '{"title":"A 50 N pull at 30° above horizontal","steps":[{"latex":"F_x = 50\\cos 30° \\approx 43.3\\ \\text{N}","explanation":""},{"latex":"F_y = 50\\sin 30° = 25\\ \\text{N}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a95bb0ace308ec', 'les_ac2e54dd59fd87', 'learn', 3, 'worked_example', '{"title":"A plane flies 200 km/h east in a 50 km/h wind blowing north","steps":[{"latex":"v = \\sqrt{200^2 + 50^2} \\approx 206\\ \\text{km/h}","explanation":""},{"latex":"\\theta = \\tan^{-1}\\tfrac{50}{200} \\approx 14.0° \\text{ north of east}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_2bcccf92649497', 'les_ac2e54dd59fd87', 'experiment', 4, 'activity', '{"activity":"vectors","title":"Build a vector from components","params":{"ux":4,"uy":0,"vx":0,"vy":1}}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_9f3b52a337e44d', 'les_ac2e54dd59fd87', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Engineers resolve cable tensions on bridges into horizontal and vertical parts; video games move characters by adding velocity components each frame."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_6ec1f29f8ec671', 'les_ac2e54dd59fd87', 1, 'practice', 'numeric', 1, 'Find the horizontal component of a 20 m/s velocity at 60° above horizontal.', '{"answer":10,"tolerance":0.01,"unit":"m/s"}', '[]', '$20\cos 60° = 10$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_aee7c08db59708', 'les_ac2e54dd59fd87', 2, 'practice', 'numeric', 2, 'Components are $A_x = 6$ and $A_y = 8$. Find the magnitude.', '{"answer":10}', '[]', '$\sqrt{36 + 64}$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_a95bb0ace308ec', 'les_ac2e54dd59fd87', 3, 'practice', 'numeric', 2, 'For those components, find the angle above the $+x$-axis, in degrees, to one decimal place.', '{"answer":53.1,"tolerance":0.1,"unit":"°"}', '[]', '$\tan^{-1}\frac{8}{6} \approx 53.1°$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_2bcccf92649497', 'les_ac2e54dd59fd87', 4, 'review', 'multiple_choice', 3, 'A vector has $A_x = -3$ and $A_y = 3$. Its direction is…', '{"choices":["45°","135°","−45°","225°"],"answer":1}', '[]', 'Second quadrant: $180° - 45°$.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_ac2e54dd59fd87', (SELECT id FROM concepts WHERE slug = 'vectors'));

-- Lesson: work-physics
INSERT OR IGNORE INTO lessons (id, slug, title, summary, estimated_minutes, status, published_at) VALUES ('les_c8e6b25065264f', 'work-physics', 'Work', 'Compute the work done by a constant force, including the angle between force and displacement, and recognize positive, negative and zero work.', 25, 'published', strftime('%Y-%m-%dT%H:%M:%SZ', 'now'));
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_2a9f10afa0aa2d', 'les_c8e6b25065264f', 1, 'Compute W = Fd cos θ in joules.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_98b778501a0f2e', 'les_c8e6b25065264f', 2, 'Decide when work is positive, negative or zero.');
INSERT OR IGNORE INTO lesson_objectives (id, lesson_id, position, text) VALUES ('lobj_8ffeb53dbbe68e', 'les_c8e6b25065264f', 3, 'Find total work as the sum of works by each force.');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_2a9f10afa0aa2d', 'les_c8e6b25065264f', 'learn', 1, 'definition', '{"term":"Work","body":"A constant force $F$ acting over a displacement $d$ at angle $\\theta$ does work $W = Fd\\cos\\theta$, measured in joules (1 J = 1 N·m). Only the component of force along the motion does work."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_98b778501a0f2e', 'les_c8e6b25065264f', 'learn', 2, 'worked_example', '{"title":"A 50 N pull at 30° above horizontal drags a sled 10 m","steps":[{"latex":"W = 50(10)\\cos 30° \\approx 433\\ \\text{J}","explanation":""}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_8ffeb53dbbe68e', 'les_c8e6b25065264f', 'learn', 3, 'worked_example', '{"title":"Lifting a 10 kg box 2 m at constant speed","steps":[{"latex":"W_{\\text{you}} = mgh = 10(9.8)(2) = 196\\ \\text{J}","explanation":""},{"latex":"W_{\\text{gravity}} = -196\\ \\text{J}","explanation":"Force opposite the motion."}]}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_a476d26714a78e', 'les_c8e6b25065264f', 'learn', 4, 'callout', '{"tone":"tip","title":"Zero work","body":"A force perpendicular to motion does no work: the normal force on a sliding box, or gravity on a satellite in a circular orbit."}');
INSERT OR IGNORE INTO lesson_blocks (id, lesson_id, mode, position, kind, data) VALUES ('blk_584b767facf38c', 'les_c8e6b25065264f', 'learn', 5, 'callout', '{"tone":"application","title":"Where this shows up","body":"Food energy is work capacity: 1 food Calorie = 4184 J, about enough to lift a 10 kg box up a 43 m building."}');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_2a9f10afa0aa2d', 'les_c8e6b25065264f', 1, 'practice', 'numeric', 1, 'A 20 N horizontal force pushes a cart 5 m. How much work does it do, in joules?', '{"answer":100,"unit":"J"}', '[]', '$20 \times 5$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_98b778501a0f2e', 'les_c8e6b25065264f', 2, 'practice', 'numeric', 2, 'How much work does friction (8 N) do on a box sliding 3 m?', '{"answer":-24,"unit":"J"}', '[]', 'Friction opposes motion: $-24$ J.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_8ffeb53dbbe68e', 'les_c8e6b25065264f', 3, 'practice', 'multiple_choice', 2, 'You carry a heavy bag horizontally at constant velocity. The work done by your upward force on the bag is…', '{"choices":["positive","negative","zero","equal to mgh"],"answer":2}', '[]', 'Upward force, horizontal displacement: $\cos 90° = 0$.');
INSERT OR IGNORE INTO practice_questions (id, lesson_id, position, purpose, kind, difficulty, prompt, data, hints, solution) VALUES ('q_a476d26714a78e', 'les_c8e6b25065264f', 4, 'review', 'numeric', 3, 'A 100 N force at 60° to the displacement acts over 4 m. Find the work, in joules.', '{"answer":200,"unit":"J"}', '[]', '$100 \cdot 4 \cdot 0.5$.');
INSERT OR IGNORE INTO concepts (id, subject_id, slug, name, description) VALUES ('cpt_173d9168467e6c', 'subj_phys', 'energy', 'Work and energy', 'Work, kinetic and potential energy, conservation of energy and power.');
INSERT OR IGNORE INTO lesson_concepts (lesson_id, concept_id) VALUES ('les_c8e6b25065264f', (SELECT id FROM concepts WHERE slug = 'energy'));
